/// <reference types="@cloudflare/vitest-pool-workers/types" />

import type {
  HnsAuthoritativeDnsValidatorInputV1,
  HnsChainAuthorityRecord,
} from "@pirate/application/namespace-ownership";
import type { Sha256Hex as Sha256HexValue } from "@pirate/domain/verification";
import { describe, expect, it } from "vitest";
import { makeHnsAuthoritativeDnsValidatorV1 } from "../../apps/hns-owner-verifier/src/owner-authoritative-dns-policy-v1.ts";

const DNSKEY_REQUEST = "000100000001000000000001086a617a6c65657577000030000100002904d0000080000000";
const CONTROL_REQUEST =
  "000200000001000000000001075f706972617465086a617a6c65657577000010000100002904d0000080000000";

const vectors = [
  {
    algorithm: 8,
    ds: [46091, 8, 2, "9e07ccd248cacd8c42686dc34eedafad5222107b0dabb084550da107b038477a"],
    dnskey:
      "",
    control:
      "",
  },
  {
    algorithm: 10,
    ds: [
      63501,
      10,
      4,
      "f810376a81769817aa42b2975345b028aea91e7db2148719a9e8b3cd9169f5013fbedaed3cfd30ef811b7d32fb99dc82",
    ],
    dnskey:
      "",
    control:
      "",
  },
  {
    algorithm: 13,
    ds: [41413, 13, 2, "48a5eeb5eb4028e9aa31fa631cf111a002ba389fa6cfe0c9ad67eb2d941ad38b"],
    dnskey:
      "",
    control:
      "",
  },
  {
    algorithm: 14,
    ds: [
      43388,
      14,
      4,
      "11b21cabbbe449d137e7acd5567931a9afccca7c43cfcf668c6be89c561b3afbd80fbfd17e44b5903936111d19fd47f6",
    ],
    dnskey:
      "",
    control:
      "",
  },
  {
    algorithm: 15,
    ds: [31144, 15, 2, "cdc9c4dfe2d72664f28fed5f4dc3f4a38ea59faaf6490337d1e3f9a33e4b7c3c"],
    dnskey:
      "",
    control:
      "",
  },
] as const;

function fromHex(value: string): Uint8Array {
  return Uint8Array.from({ length: value.length / 2 }, (_, index) =>
    Number.parseInt(value.slice(index * 2, index * 2 + 2), 16),
  );
}

function inputFor(vector: (typeof vectors)[number]): HnsAuthoritativeDnsValidatorInputV1 {
  const authorityRecords: ReadonlyArray<HnsChainAuthorityRecord> = [
    ["NS", "ns1.jazleeuw"],
    ["GLUE4", "ns1.jazleeuw", "192.0.2.53"],
    ["DS", vector.ds[0], vector.ds[1], vector.ds[2], vector.ds[3]],
  ];
  return {
    driver_reference: "authoritative-dns:workerd-golden",
    view_id: "dns-view-a",
    root_label: "jazleeuw",
    authority_records: authorityRecords,
    chain_authority_digest: "1".repeat(64) as Sha256HexValue,
    authority_nameserver: "ns1.jazleeuw",
    authority_address_family: "GLUE4",
    authority_address: "192.0.2.53",
    dnskey_request_bytes: fromHex(DNSKEY_REQUEST),
    dnskey_response_bytes: fromHex(vector.dnskey),
    control_request_bytes: fromHex(CONTROL_REQUEST),
    control_response_bytes: fromHex(vector.control),
    validation_database_time: "2026-02-02T12:00:00.000Z",
    signal: new AbortController().signal,
  };
}

describe("HNS DNSSEC policy v1 WebCrypto capability (workerd)", () => {
  it("validates immutable golden packets for every accepted algorithm", async () => {
    const validator = await makeHnsAuthoritativeDnsValidatorV1();
    for (const vector of vectors) {
      const result = await validator.validate(inputFor(vector));
      expect(result.dnssec_validation, `algorithm ${vector.algorithm}`).toBe("secure");
    }
  });
});
